create or replace function public.kd_set_group_poll_votes(p_poll_id uuid, p_option_ids uuid[]) returns boolean language plpgsql security definer set search_path = public as $$ declare v_user uuid := auth.uid(); v_conv uuid; v_closed boolean; v_multiple boolean; begin if v_user is null then raise exception 'not authenticated'; end if; select conversation_id, closed, multiple_choice into v_conv, v_closed, v_multiple from public.kd_group_polls where id=p_poll_id; if v_conv is null then raise exception 'poll not found'; end if; if v_closed then raise exception 'poll closed'; end if; if not exists (select 1 from public.kd_conversation_members where conversation_id=v_conv and user_id=v_user) then raise exception 'not a member'; end if; if exists (select 1 from unnest(coalesce(p_option_ids, '{}'::uuid[])) x where not exists (select 1 from public.kd_group_poll_options o where o.id=x and o.poll_id=p_poll_id)) then raise exception 'invalid option'; end if; if not v_multiple and coalesce(array_length(p_option_ids,1),0)>1 then raise exception 'single choice poll'; end if; delete from public.kd_group_poll_votes where poll_id=p_poll_id and user_id=v_user; insert into public.kd_group_poll_votes(poll_id,option_id,user_id) select p_poll_id,x,v_user from unnest(coalesce(p_option_ids, '{}'::uuid[])) x; return true; end; $$; grant execute on function public.kd_set_group_poll_votes(uuid,uuid[]) to authenticated;